public int jump(int[] nums) {
    int jumps = 0, curEnd = 0, curFarthest = 0;
    for (int i = 0; i < nums.length - 1; i++) {
        curFarthest = Math.max(curFarthest, i + nums[i]);
        if (i == curEnd) {
            jumps++;
            curEnd = curFarthest;
            if (curEnd >= nums.length - 1) break;
        }
    }
    return jumps;
}

public int eraseOverlapIntervals(int[][] intervals) {
    Arrays.sort(intervals, (a, b) -> Integer.compare(a[1], b[1]));
    int count = 0, lastEnd = Integer.MIN_VALUE;
    for (int[] interval : intervals) {
        if (interval[0] >= lastEnd) {
            lastEnd = interval[1];
        } else {
            count++; // Overlapping, needs removal
        }
    }
    return count;
}

public int numRescueBoats(int[] people, int limit) {
    Arrays.sort(people);
    int boats = 0, left = 0, right = people.length - 1;
    while (left <= right) {
        if (people[left] + people[right] <= limit) {
            left++; // Light person fits with heavy person
        }
        right--; // Heavy person always takes a boat
        boats++;
    }
    return boats;
}

public int[][] reconstructQueue(int[][] people) {
    Arrays.sort(people, (a, b) -> a[0] == b[0] ? a[1] - b[1] : b[0] - a[0]);
    List<int[]> result = new ArrayList<>();
    for (int[] p : people) {
        result.add(p[1], p); // Insert at index k
    }
    return result.toArray(new int[people.length][]);
}

public int candy(int[] ratings) {
    int n = ratings.length;
    int[] candies = new int[n];
    Arrays.fill(candies, 1);

    for (int i = 1; i < n; i++) {
        if (ratings[i] > ratings[i - 1]) {
            candies[i] = candies[i - 1] + 1;
        }
    }
    for (int i = n - 2; i >= 0; i--) {
        if (ratings[i] > ratings[i + 1]) {
            candies[i] = Math.max(candies[i], candies[i + 1] + 1);
        }
    }
    int sum = 0;
    for (int c : candies) sum += c;
    return sum;
}

public int canCompleteCircuit(int[] gas, int[] cost) {
    int totalTank = 0, currTank = 0, startStation = 0;
    for (int i = 0; i < gas.length; i++) {
        int netGain = gas[i] - cost[i];
        totalTank += netGain;
        currTank += netGain;
        if (currTank < 0) {
            startStation = i + 1; // Reset start
            currTank = 0;         // Reset tank
        }
    }
    return totalTank >= 0 ? startStation : -1;
}

public int leastInterval(char[] tasks, int n) {
    int[] freq = new int[26];
    for (char c : tasks) freq[c - 'A']++;
    int maxFreq = 0, countMax = 0;
    for (int f : freq) {
        if (f > maxFreq) {
            maxFreq = f;
            countMax = 1;
        } else if (f == maxFreq) {
            countMax++;
        }
    }
    int partCount = maxFreq - 1;
    int partLength = n - (countMax - 1);
    int emptySlots = partCount * partLength;
    int availableTasks = tasks.length - (maxFreq * countMax);
    int idles = Math.max(0, emptySlots - availableTasks);
    return tasks.length + idles;
}

public String largestNumber(int[] nums) {
    String[] strs = new String[nums.length];
    for (int i = 0; i < nums.length; i++) strs[i] = String.valueOf(nums[i]);
    Arrays.sort(strs, (a, b) -> (b + a).compareTo(a + b));
    if (strs[0].equals("0")) return "0"; 
    StringBuilder sb = new StringBuilder();
    for (String s : strs) sb.append(s);
    return sb.toString();
}

public int minPlatforms(int[] arr, int[] dep) {
    Arrays.sort(arr);
    Arrays.sort(dep);
    int platformsNeeded = 0, maxPlatforms = 0;
    int i = 0, j = 0;
    while (i < arr.length && j < dep.length) {
        if (arr[i] <= dep[j]) {
            platformsNeeded++;
            i++;
            maxPlatforms = Math.max(maxPlatforms, platformsNeeded);
        } else {
            platformsNeeded--;
            j++;
        }
    }
    return maxPlatforms;
}
